// SeederCharID is the NPC character ID used as the market seeder (Seeder NPC).
// Orders under this ID are regenerated by SeedNPCMarketOrders.
const SeederCharID = 90000001

// AdminSeederCharID owns NPC market orders hand-placed through the ESP admin
// panel. They behave like Seeder orders to the matching engine but survive
// SeedNPCMarketOrders' purge, so admins can pin permanent NPC orders.
const AdminSeederCharID = 90000002

// IsNPCSeeder reports whether charID is one of the synthetic NPC market
// owners (auto seeder, admin seeder, or the resale shelf). The matching engine
// uses this to skip wallet/journal/notification for NPC counterparties.
func IsNPCSeeder(charID int64) bool {
	return charID == SeederCharID || charID == AdminSeederCharID ||
		charID == ResaleSeederCharID
}

// EnsureWalletJournalTable creates the wallet journal table if it does not
// exist, so a fresh database works without manual SQL.  Written by mission
// rewards, bounties and market transactions; read by account.GetJournal.
// Call once at server startup.
func EnsureWalletJournalTable(ctx context.Context, db *sql.DB) error {
	_, err := db.ExecContext(ctx, `
		CREATE TABLE IF NOT EXISTS market_journal (
			refID       BIGINT AUTO_INCREMENT PRIMARY KEY,
			characterID INT NOT NULL,
			transDate   BIGINT NOT NULL,
			refTypeID   INT NOT NULL,
			ownerID1    INT DEFAULT NULL,
			ownerID2    INT DEFAULT NULL,
			argID1      VARCHAR(255) DEFAULT NULL,
			accountID   INT NOT NULL DEFAULT 0,
			amount      DOUBLE NOT NULL DEFAULT 0,
			balance     DOUBLE NOT NULL DEFAULT 0,
			reason      TEXT,
			accountKey  INT NOT NULL DEFAULT 1000,
			INDEX idx_char (characterID)
		) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3`)
	return err
}

// EnsureTransactionOwnerColumn adds market_transactions.characterID, the row owner (whose
// Transactions tab it belongs to), separate from clientID, the counterparty in the Client
// column. Existing rows are backfilled with characterID = clientID because the real
// counterparty was never recorded. See docs/db-notes.md#transaction-owner-column.
func EnsureTransactionOwnerColumn(ctx context.Context, db *sql.DB) error {
	var exists int
	err := db.QueryRowContext(ctx, `
		SELECT COUNT(*) FROM information_schema.COLUMNS
		WHERE TABLE_SCHEMA = DATABASE()
		  AND TABLE_NAME   = 'market_transactions'
		  AND COLUMN_NAME  = 'characterID'`).Scan(&exists)
	if err != nil {
		return fmt.Errorf("EnsureTransactionOwnerColumn probe: %w", err)
	}
	if exists > 0 {
		return nil
	}
	if _, err := db.ExecContext(ctx, `
		ALTER TABLE market_transactions
		ADD COLUMN characterID INT UNSIGNED NOT NULL DEFAULT 0 AFTER transactionType`); err != nil {
		return fmt.Errorf("EnsureTransactionOwnerColumn add column: %w", err)
	}
	if _, err := db.ExecContext(ctx, `
		UPDATE market_transactions SET characterID = clientID WHERE characterID = 0`); err != nil {
		return fmt.Errorf("EnsureTransactionOwnerColumn backfill: %w", err)
	}
	if _, err := db.ExecContext(ctx, `
		ALTER TABLE market_transactions
		ADD INDEX idx_mt_owner_date (characterID, transactionDateTime), ALGORITHM=INPLACE, LOCK=NONE`); err != nil {
		return fmt.Errorf("EnsureTransactionOwnerColumn index: %w", err)
	}
	return nil
}

// ── Parent lookups ────────────────────────────────────────────────────────────

// StationParents holds the location hierarchy for a station.
type StationParents struct {
	SolarSystemID   int64
	ConstellationID int64
	RegionID        int64
}

// GetStationParents returns the solarSystemID, constellationID, and regionID
// for the given stationID by querying staStations.
func GetStationParents(ctx context.Context, db *sql.DB, stationID int64) (*StationParents, error) {
	var p StationParents
	err := db.QueryRowContext(ctx,
		`SELECT solarSystemID, constellationID, regionID FROM staStations WHERE stationID = ?`,
		stationID,
	).Scan(&p.SolarSystemID, &p.ConstellationID, &p.RegionID)
	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return nil, fmt.Errorf("GetStationParents: station %d not found", stationID)
		}
		return nil, fmt.Errorf("GetStationParents: %w", err)
	}
	return &p, nil
}

// GetSystemParents returns the constellationID and regionID for a solarSystem.
func GetSystemParents(ctx context.Context, db *sql.DB, solarSystemID int64) (constellationID, regionID int64, err error) {
	err = db.QueryRowContext(ctx,
		`SELECT constellationID, regionID FROM mapSolarSystems WHERE solarSystemID = ?`,
		solarSystemID,
	).Scan(&constellationID, &regionID)
	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return 0, 0, fmt.Errorf("GetSystemParents: system %d not found", solarSystemID)
		}
		return 0, 0, fmt.Errorf("GetSystemParents: %w", err)
	}
	return
}

// ── GetStationAsks ────────────────────────────────────────────────────────────

// stationAsksCols is the column set of marketProxy.GetStationAsks, a util.IndexRowset
// keyed by typeID.
var stationAsksCols = []string{"typeID", "price", "volRemaining", "stationID"}

// GetStationAsks returns a util.IndexRowset of the best sell-order price per
// typeID at a given station, mirroring MarketDB::GetStationAsks.
func GetStationAsks(ctx context.Context, db *sql.DB, stationID int64) (marshal.PyRep, error) {
	rows, err := db.QueryContext(ctx,
		`SELECT typeID, MAX(price) AS price, SUM(volRemaining) AS volRemaining, stationID
		   FROM market_orders
		  WHERE stationID = ? AND bid = 0 AND orderState = 1 AND volRemaining > 0
		  GROUP BY typeID`,
		stationID,
	)
	if err != nil {
		return makeIndexRowset("typeID", stationAsksCols, nil), nil
	}
	defer rows.Close()

	var result [][]marshal.PyRep
	for rows.Next() {
		var typeID, vol, sid int64
		var price float64
		if err := rows.Scan(&typeID, &price, &vol, &sid); err != nil {
			return nil, fmt.Errorf("GetStationAsks scan: %w", err)
		}
		result = append(result, []marshal.PyRep{
			intRep(typeID), floatRep(price), intRep(vol), intRep(sid),
		})
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("GetStationAsks rows: %w", err)
	}
	return makeIndexRowset("typeID", stationAsksCols, result), nil
}

