// ── GetOrders ─────────────────────────────────────────────────────────────────

// marketOrderCols is the GetOrders rowset layout (jumps computed as 0). marketQuote
// indexes constellationID unconditionally, so the column must exist. Rows are blue.DBRows,
// not util.Rows: GetBestMatchableBid copies bids into a dbutil.RowList, which rejects
// anything else. jumps is R8 because RefreshJumps writes the pathfinder's float into it.
var marketOrderCols = []packedCol{
	{"price", dbtypeCY},
	{"volRemaining", dbtypeR8},
	{"typeID", dbtypeI4},
	{"range", dbtypeI4},
	{"orderID", dbtypeI8},
	{"volEntered", dbtypeI4},
	{"minVolume", dbtypeI4},
	{"bid", dbtypeBool},
	{"issued", dbtypeFiletime},
	{"duration", dbtypeI4},
	{"stationID", dbtypeI4},
	{"regionID", dbtypeI4},
	{"solarSystemID", dbtypeI4},
	{"constellationID", dbtypeI4},
	{"jumps", dbtypeR8},
}

// GetMarketOrders returns a PyTuple(2) of [sellOrders, buyOrders] dbutil.RowLists
// for a given regionID + typeID, mirroring MarketDB::GetOrders.
func GetMarketOrders(ctx context.Context, db *sql.DB, regionID, typeID int64) (marshal.PyRep, error) {
	sellRows, err := queryOrderRows(ctx, db, regionID, typeID, false)
	if err != nil {
		return nil, fmt.Errorf("GetMarketOrders sell: %w", err)
	}
	buyRows, err := queryOrderRows(ctx, db, regionID, typeID, true)
	if err != nil {
		return nil, fmt.Errorf("GetMarketOrders buy: %w", err)
	}
	return marshal.PyTuple{Items: []marshal.PyRep{
		makePackedRowList(marketOrderCols, sellRows),
		makePackedRowList(marketOrderCols, buyRows),
	}}, nil
}

func queryOrderRows(ctx context.Context, db *sql.DB, regionID, typeID int64, bid bool) ([][]any, error) {
	bidVal := 0
	if bid {
		bidVal = 1
	}
	rows, err := db.QueryContext(ctx,
		`SELECT o.price, o.volRemaining, o.typeID, o.`+"`range`"+`, o.orderID,
		        o.volEntered, o.minVolume, o.bid, o.issued, o.duration,
		        o.stationID, o.regionID, o.solarSystemID,
		        COALESCE(st.constellationID, 0) AS constellationID, 0 AS jumps
		   FROM market_orders o
		   LEFT JOIN staStations st ON st.stationID = o.stationID
		  WHERE o.regionID = ? AND o.typeID = ? AND o.bid = ? AND o.orderState = 1 AND o.volRemaining > 0`,
		regionID, typeID, bidVal,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var result [][]any
	for rows.Next() {
		var price float64
		var volRemaining, typeIDv, rangeV, orderID int64
		var volEntered, minVolume int64
		var bidV float64
		var issued int64
		var duration int64
		var stationID, regionIDv, solarSystemID, constellationID int64
		var jumps int64
		if err := rows.Scan(
			&price, &volRemaining, &typeIDv, &rangeV, &orderID,
			&volEntered, &minVolume, &bidV, &issued, &duration,
			&stationID, &regionIDv, &solarSystemID, &constellationID, &jumps,
		); err != nil {
			return nil, fmt.Errorf("queryOrderRows scan: %w", err)
		}
		result = append(result, []any{
			price, float64(volRemaining), typeIDv, rangeV, orderID,
			volEntered, minVolume, bidV != 0, issued, duration,
			stationID, regionIDv, solarSystemID, constellationID, float64(jumps),
		})
	}
	return result, rows.Err()
}

// ── GetOldPriceHistory / GetNewPriceHistory ───────────────────────────────────

// priceHistoryDescriptor returns the blue.DBRowDescriptor for the 6 price-history
// columns in the exact ordering used by MarketDB::GetOldPriceHistory and
// GetNewPriceHistory (matches the C++ DBColumnOrdering).
func priceHistoryDescriptor() marshal.PyPackedRowHeader {
	pair := func(name string, dbtype uint64) marshal.PyRep {
		return marshal.PyTuple{Items: []marshal.PyRep{
			marshal.PyString{Value: name},
			marshal.PyInt{Value: dbtype},
		}}
	}
	return marshal.PyPackedRowHeader{
		HeaderType: marshal.PyString{Value: "blue.DBRowDescriptor", IsType1: true},
		Arguments: marshal.PyTuple{Items: []marshal.PyRep{
			marshal.PyTuple{Items: []marshal.PyRep{
				pair("historyDate", dbtypeFiletime),
				pair("lowPrice", dbtypeCY),
				pair("highPrice", dbtypeCY),
				pair("avgPrice", dbtypeCY),
				pair("volume", dbtypeI8),
				pair("orders", dbtypeI4),
			}},
		}},
		// Rows stay nil; the packed rows travel in the separate PyList.
	}
}

// packPriceRow zero-compresses one history row, little-endian: historyDate (FILETIME),
// lowPrice, highPrice, avgPrice (DBTYPE_CY, price * 10000) and volume at 8 bytes each,
// then orders at 4 bytes: 44 bytes raw.
func packPriceRow(histDate, volume, orders int64, low, high, avg float64) []byte {
	raw := make([]byte, 44)
	binary.LittleEndian.PutUint64(raw[0:], uint64(histDate))
	binary.LittleEndian.PutUint64(raw[8:], uint64(int64(low*10000)))
	binary.LittleEndian.PutUint64(raw[16:], uint64(int64(high*10000)))
	binary.LittleEndian.PutUint64(raw[24:], uint64(int64(avg*10000)))
	binary.LittleEndian.PutUint64(raw[32:], uint64(volume))
	binary.LittleEndian.PutUint32(raw[40:], uint32(orders))
	return marshal.PackZeroCompressed(raw)
}

// GetOldPriceHistory returns market_history_old rows in the same (DBRowDescriptor,
// [packed_rows]) tuple as GetNewPriceHistory. historyDate is stored as Unix seconds and
// converted to FILETIME before packing.
func GetOldPriceHistory(ctx context.Context, db *sql.DB, regionID, typeID int64) (marshal.PyRep, error) {
	rows, err := db.QueryContext(ctx,
		`SELECT historyDate, lowPrice, highPrice, avgPrice, volume, orders
		   FROM market_history_old
		  WHERE regionID = ? AND typeID = ? AND historyDate >= ?
		  ORDER BY historyDate`,
		regionID, typeID, floorDay(retentionNow())-(priceChartDays+1)*unixDay,
	)
	desc := priceHistoryDescriptor()
	emptyResult := marshal.PyTuple{Items: []marshal.PyRep{desc, marshal.PyList{}}}
	if err != nil {
		return emptyResult, nil
	}
	defer rows.Close()

	var packedRows []marshal.PyRep
	for rows.Next() {
		var histDate, volume, orders int64
		var low, high, avg float64
		if err := rows.Scan(&histDate, &low, &high, &avg, &volume, &orders); err != nil {
			return nil, err
		}
		// Unix seconds to FILETIME (100-ns ticks since 1601-01-01).
		histFiletime := (histDate + 11644473600) * 10000000
		packedRows = append(packedRows, marshal.PyPackedRow{
			Header: desc,
			Data:   packPriceRow(histFiletime, volume, orders, low, high, avg),
		})
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return marshal.PyTuple{Items: []marshal.PyRep{
		desc,
		marshal.PyList{Items: packedRows},
	}}, nil
}

// GetNewPriceHistory aggregates market_transactions into the (DBRowDescriptor,
// [packed_rows]) tuple the client builds a DBRowset from (a descriptor, not a util.Rowset).
// It covers only the days the rollup has not folded into market_history_old
// (pricehistoryroll.go), at most the chart's year. See docs/db-notes.md#price-history-index.
func GetNewPriceHistory(ctx context.Context, db *sql.DB, regionID, typeID int64) (marshal.PyRep, error) {
	const win32Day = int64(864000000000) // 1 day in 100-ns windows ticks
	from := newHistoryFrom(cachedRolledThrough(ctx, db), retentionNow())
	const q = `
		SELECT transactionDateTime - (transactionDateTime % ?) AS historyDate,
		       MIN(price) AS lowPrice,
		       MAX(price) AS highPrice,
		       AVG(price) AS avgPrice,
		       SUM(quantity) AS volume,
		       COUNT(*) AS orders
		  FROM market_transactions /*hint*/
		 WHERE transactionType = 1 AND typeID = ? AND transactionDateTime >= ?
		   AND regionID = ?
		 GROUP BY historyDate
		 ORDER BY historyDate`
	args := []any{win32Day, typeID, UnixToWin32(from), regionID}
	rows, err := db.QueryContext(ctx,
		strings.Replace(q, "/*hint*/", "FORCE INDEX (idx_mt_type_item_date)", 1), args...)
	if err != nil {
		// A hint naming a missing index is an error, so retry unhinted rather than blank the chart.
		rows, err = db.QueryContext(ctx, q, args...)
	}
	desc := priceHistoryDescriptor()
	emptyResult := marshal.PyTuple{Items: []marshal.PyRep{desc, marshal.PyList{}}}
	if err != nil {
		return emptyResult, nil
	}
	defer rows.Close()

	var packedRows []marshal.PyRep
	for rows.Next() {
		var histDate, volume, orders int64
		var low, high, avg float64
		if err := rows.Scan(&histDate, &low, &high, &avg, &volume, &orders); err != nil {
			return nil, err
		}
		packedRows = append(packedRows, marshal.PyPackedRow{
			Header: desc,
			Data:   packPriceRow(histDate, volume, orders, low, high, avg),
		})
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return marshal.PyTuple{Items: []marshal.PyRep{
		desc,
		marshal.PyList{Items: packedRows},
	}}, nil
}

// ── GetCharOrders ─────────────────────────────────────────────────────────────

var charOrderCols = []string{
	"orderID", "typeID", "charID", "regionID", "stationID",
	"range", "bid", "price", "volEntered", "volRemaining",
	"issued", "orderState", "minVolume", "contraband",
	"accountID", "duration", "isCorp", "solarSystemID", "escrow",
}

// GetCharOrders returns a util.Rowset of all open orders placed by characterID,
// mirroring MarketDB::GetCharOrders.
func GetCharOrders(ctx context.Context, db *sql.DB, characterID int64) (marshal.PyRep, error) {
	rows, err := db.QueryContext(ctx,
		`SELECT orderID, typeID, charID, regionID, stationID,
		        `+"`range`"+`, bid, price, volEntered, volRemaining,
		        issued, orderState, minVolume, contraband,
		        accountID, duration, isCorp, solarSystemID, escrow
		   FROM market_orders
		  WHERE charID = ? AND orderState = 1`,
		characterID,
	)
	if err != nil {
		return makeRowset(charOrderCols, nil), nil
	}
	defer rows.Close()
	return scanCharOrderRows(rows)
}

// scanCharOrderRows builds a charOrderCols rowset from a query over the
// market_orders columns in charOrderCols order. Shared by GetCharOrders and
// GetCorporationOrders.
func scanCharOrderRows(rows *sql.Rows) (marshal.PyRep, error) {
	var result [][]marshal.PyRep
	for rows.Next() {
		var orderID, typeID, charID, regionID, stationID int64
		var rangeV int64
		var bidV int64
		var price float64
		var volEntered, volRemaining int64
		var issued int64
		var orderState, minVolume int64
		var contraband int64
		var accountID, duration int64
		var isCorp int64
		var solarSystemID sql.NullInt64
		var escrow float64
		if err := rows.Scan(
			&orderID, &typeID, &charID, &regionID, &stationID,
			&rangeV, &bidV, &price, &volEntered, &volRemaining,
			&issued, &orderState, &minVolume, &contraband,
			&accountID, &duration, &isCorp, &solarSystemID, &escrow,
		); err != nil {
			return nil, fmt.Errorf("scanCharOrderRows: %w", err)
		}
		result = append(result, []marshal.PyRep{
			intRep(orderID), intRep(typeID), intRep(charID), intRep(regionID), intRep(stationID),
			// bid must not be a float: orders.py ShowOrders indexes [sellScroll, buyScroll][order.bid],
			// which raises for a PyReal. PyBool matches the browse rowset.
			intRep(rangeV), marshal.PyBool{Value: bidV != 0}, floatRep(price), intRep(volEntered), intRep(volRemaining),
			intRep(issued), intRep(orderState), intRep(minVolume), intRep(contraband),
			intRep(accountID), intRep(duration), intRep(isCorp), nullIntRep(solarSystemID), floatRep(escrow),
		})
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return makeRowset(charOrderCols, result), nil
}

// ── GetMarketGroups ───────────────────────────────────────────────────────────

// GetMarketGroups builds the util.FilterRowset for marketProxy.GetMarketGroups, keyed by
// parentGroupID. Each entry is a 7-element list: marketGroupID, parentGroupID, name,
// description, graphicID, hasTypes, typeIDs.
func GetMarketGroups(ctx context.Context, db *sql.DB) (marshal.PyRep, error) {
	// Step 1: build typeID sets per marketGroupID from invTypes.
	typeRows, err := db.QueryContext(ctx,
		`SELECT marketGroupID, typeID
		   FROM invTypes
		  WHERE marketGroupID IS NOT NULL AND published = 1
		  ORDER BY marketGroupID`)
	if err != nil {
		return marshal.PyNone{}, fmt.Errorf("GetMarketGroups types: %w", err)
	}
	defer typeRows.Close()

	// directTypes maps marketGroupID to the typeIDs directly in that group.
	directTypes := map[int64][]int64{}
	for typeRows.Next() {
		var mgID, typeID int64
		if err := typeRows.Scan(&mgID, &typeID); err != nil {
			return nil, err
		}
		directTypes[mgID] = append(directTypes[mgID], typeID)
	}
	typeRows.Close()

	// Step 2: load group hierarchy.
	groupRows, err := db.QueryContext(ctx,
		`SELECT marketGroupID, parentGroupID, marketGroupName, description, graphicID, hasTypes
		   FROM invMarketGroups
		  ORDER BY marketGroupID`)
	if err != nil {
		return marshal.PyNone{}, fmt.Errorf("GetMarketGroups groups: %w", err)
	}
	defer groupRows.Close()

	type groupInfo struct {
		marketGroupID int64
		parentGroupID sql.NullInt64
		name          string
		description   string
		graphicID     sql.NullInt64
		hasTypes      int64
		children      []int64
	}
	groups := map[int64]*groupInfo{}
	var allGroupIDs []int64
	for groupRows.Next() {
		g := &groupInfo{}
		if err := groupRows.Scan(&g.marketGroupID, &g.parentGroupID, &g.name, &g.description, &g.graphicID, &g.hasTypes); err != nil {
			return nil, err
		}
		groups[g.marketGroupID] = g
		allGroupIDs = append(allGroupIDs, g.marketGroupID)
	}
	groupRows.Close()

	// Build the parent to children mapping.
	for _, id := range allGroupIDs {
		g := groups[id]
		if g.parentGroupID.Valid {
			pid := g.parentGroupID.Int64
			if p, ok := groups[pid]; ok {
				p.children = append(p.children, id)
			}
		}
	}

	// Step 3: propagate type IDs upward (bottom-up), so a parent's type list includes its
	// whole subtree.
	allTypes := map[int64]map[int64]struct{}{} // groupID to typeIDs
	for mgID, types := range directTypes {
		if allTypes[mgID] == nil {
			allTypes[mgID] = map[int64]struct{}{}
		}
		for _, t := range types {
			allTypes[mgID][t] = struct{}{}
		}
	}

	var propagate func(gid int64)
	propagate = func(gid int64) {
		g, ok := groups[gid]
		if !ok {
			return
		}
		for _, childID := range g.children {
			propagate(childID)
			// merge child's types into this group.
			for t := range allTypes[childID] {
				if allTypes[gid] == nil {
					allTypes[gid] = map[int64]struct{}{}
				}
				allTypes[gid][t] = struct{}{}
			}
		}
	}
	for _, id := range allGroupIDs {
		g := groups[id]
		if !g.parentGroupID.Valid {
			propagate(id)
		}
	}

	// Step 4: build the util.FilterRowset. Each parentGroupID key holds a list of
	// MarketGroup_Entry lists.

	parentLists := map[int64][]marshal.PyRep{} // parentID to encoded entries

	for _, gid := range allGroupIDs {
		g := groups[gid]

		// Build the types list for this group.
		typeSet := allTypes[gid]
		typeItems := make([]marshal.PyRep, 0, len(typeSet))
		for t := range typeSet {
			typeItems = append(typeItems, marshal.PyInt{Value: uint64(t)})
		}

		var parentRep marshal.PyRep
		var parentKey int64
		if g.parentGroupID.Valid {
			parentRep = intRep(g.parentGroupID.Int64)
			parentKey = g.parentGroupID.Int64
		} else {
			parentRep = marshal.PyNone{}
			parentKey = -1
		}

		var graphicRep marshal.PyRep
		if g.graphicID.Valid {
			graphicRep = intRep(g.graphicID.Int64)
		} else {
			graphicRep = marshal.PyNone{}
		}

		entry := marshal.PyList{Items: []marshal.PyRep{
			intRep(g.marketGroupID),
			parentRep,
			strRep(g.name),
			strRep(g.description),
			graphicRep,
			intRep(g.hasTypes),
			marshal.PyList{Items: typeItems},
		}}
		parentLists[parentKey] = append(parentLists[parentKey], entry)
	}

	// Build the items PyDict.
	items := marshal.PyDict{}
	for parentKey, entries := range parentLists {
		var k marshal.PyRep
		if parentKey == -1 {
			k = marshal.PyNone{}
		} else {
			k = marshal.PyInt{Value: uint64(parentKey)}
		}
		items.Items = append(items.Items, marshal.DictEntry{
			Key:   k,
			Value: marshal.PyList{Items: entries},
		})
	}

	header := marshal.PyList{Items: []marshal.PyRep{
		strRep("marketGroupID"), strRep("parentGroupID"), strRep("marketGroupName"),
		strRep("description"), strRep("graphicID"), strRep("hasTypes"), strRep("types"),
	}}

	return marshal.PyObject{
		Type: "util.FilterRowset",
		Args: marshal.PyDict{Items: []marshal.DictEntry{
			{Key: strRep("header"), Value: header},
			{Key: strRep("idName"), Value: strRep("parentGroupID")},
			{Key: strRep("RowClass"), Value: marshal.PyString{Value: "util.Row", IsType1: true}},
			{Key: strRep("idName2"), Value: marshal.PyNone{}},
			{Key: strRep("items"), Value: items},
		}},
	}, nil
}

// ── GetCharAssets ─────────────────────────────────────────────────────────────

// AssetItem holds a single entity row for the assets window.
type AssetItem struct {
	ItemID     int64
	TypeID     int64
	OwnerID    int64
	LocationID int64
	Flag       int64
	Contraband int64
	Singleton  int64
	Quantity   int64
	GroupID    int64
	CategoryID int64
}

// GetCharAssets returns the assetSvc.GetLocations(ownerID) response: a PyDict of stationID
// to the util.Rowset of items charID owns there (flag 4, flagHangar).
func GetCharAssets(ctx context.Context, db *sql.DB, charID int64) (marshal.PyRep, error) {
	log.Printf("[db] GetCharAssets charID=%d", charID)
	rows, err := db.QueryContext(ctx,
		`SELECT e.itemID, e.typeID, e.ownerID, e.locationID, e.flag,
		        e.contraband, e.singleton, e.quantity,
		        COALESCE(t.groupID, 0), COALESCE(g.categoryID, 0)
		   FROM entity e
		   LEFT JOIN invTypes t ON t.typeID = e.typeID
		   LEFT JOIN invGroups g ON g.groupID = t.groupID
		   INNER JOIN staStations s ON s.stationID = e.locationID
		  WHERE e.ownerID = ? AND e.flag = 4
		  ORDER BY e.locationID, e.itemID`,
		charID,
	)
	if err != nil {
		return nil, fmt.Errorf("GetCharAssets query: %w", err)
	}
	defer rows.Close()

	// Group items by locationID (stationID).
	stationItems := map[int64][][]marshal.PyRep{}
	var stationOrder []int64
	seen := map[int64]bool{}
	for rows.Next() {
		var a AssetItem
		if err := rows.Scan(&a.ItemID, &a.TypeID, &a.OwnerID, &a.LocationID,
			&a.Flag, &a.Contraband, &a.Singleton, &a.Quantity,
			&a.GroupID, &a.CategoryID); err != nil {
			return nil, fmt.Errorf("GetCharAssets scan: %w", err)
		}
		if !seen[a.LocationID] {
			seen[a.LocationID] = true
			stationOrder = append(stationOrder, a.LocationID)
		}
		stationItems[a.LocationID] = append(stationItems[a.LocationID], []marshal.PyRep{
			intRep(a.ItemID), intRep(a.TypeID), intRep(a.OwnerID), intRep(a.LocationID),
			intRep(a.Flag), intRep(a.Contraband), intRep(a.Singleton), intRep(a.Quantity),
			intRep(a.GroupID), intRep(a.CategoryID), marshal.PyNone{},
		})
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}

	assetCols := []string{
		"itemID", "typeID", "ownerID", "locationID", "flag",
		"contraband", "singleton", "quantity", "groupID", "categoryID", "customInfo",
	}

	log.Printf("[db] GetCharAssets charID=%d → %d stations", charID, len(stationOrder))
	entries := make([]marshal.DictEntry, len(stationOrder))
	for i, sid := range stationOrder {
		log.Printf("[db] GetCharAssets   stationID=%d items=%d", sid, len(stationItems[sid]))
		entries[i] = marshal.DictEntry{
			Key:   intRep(sid),
			Value: makeRowset(assetCols, stationItems[sid]),
		}
	}
	return marshal.PyDict{Items: entries}, nil
}

// GetCharHangarItems returns the util.Rowset of items charID owns at stationID with flag 4,
// the flat list InventoryBound.List() returns when the client opens the station hangar.
func GetCharHangarItems(ctx context.Context, db *sql.DB, charID, stationID int64) (marshal.PyRep, error) {
	log.Printf("[db] GetCharHangarItems charID=%d stationID=%d", charID, stationID)
	assetCols := []string{
		"itemID", "typeID", "ownerID", "locationID", "flag",
		"contraband", "singleton", "quantity", "groupID", "categoryID", "customInfo",
	}
	rows, err := db.QueryContext(ctx,
		`SELECT e.itemID, e.typeID, e.ownerID, e.locationID, e.flag,
		        e.contraband, e.singleton, e.quantity,
		        COALESCE(t.groupID, 0), COALESCE(g.categoryID, 0)
		   FROM entity e
		   LEFT JOIN invTypes t ON t.typeID = e.typeID
		   LEFT JOIN invGroups g ON g.groupID = t.groupID
		  WHERE e.ownerID = ? AND e.flag = 4 AND e.locationID = ?
		  ORDER BY t.typeID, e.itemID`,
		charID, stationID,
	)
	if err != nil {
		return nil, fmt.Errorf("GetCharHangarItems query: %w", err)
	}
	defer rows.Close()

	var result [][]marshal.PyRep
	for rows.Next() {
		var a AssetItem
		if err := rows.Scan(&a.ItemID, &a.TypeID, &a.OwnerID, &a.LocationID,
			&a.Flag, &a.Contraband, &a.Singleton, &a.Quantity,
			&a.GroupID, &a.CategoryID); err != nil {
			return nil, fmt.Errorf("GetCharHangarItems scan: %w", err)
		}
		result = append(result, []marshal.PyRep{
			intRep(a.ItemID), intRep(a.TypeID), intRep(a.OwnerID), intRep(a.LocationID),
			intRep(a.Flag), intRep(a.Contraband), intRep(a.Singleton), intRep(a.Quantity),
			intRep(a.GroupID), intRep(a.CategoryID), marshal.PyNone{},
		})
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("GetCharHangarItems rows: %w", err)
	}
	log.Printf("[db] GetCharHangarItems charID=%d stationID=%d → %d items", charID, stationID, len(result))
	return makeRowset(assetCols, result), nil
}

// GetCharStationBlueprintItems returns charID's flag 4 blueprints at stationID (types in
// invBlueprintTypes) for the S&I picker's ListStationBlueprintItems. item.py UpdateLabel
// needs the columns copy, materialLevel, productivityLevel,
// licensedProductionRunsRemaining and blueprintID.
func GetCharStationBlueprintItems(ctx context.Context, db *sql.DB, charID, stationID int64) (marshal.PyRep, error) {
	return GetOwnerBlueprintItemsAt(ctx, db, charID, stationID, []int64{4})
}

// GetOwnerBlueprintItemsAt is the blueprint picker's rowset for any owner, location and
// flag set, e.g. a corporation's blueprints in a starbase array's divisions
// (ListStationBlueprintItems(arrayID, isCorp=1)).
func GetOwnerBlueprintItemsAt(ctx context.Context, db *sql.DB, ownerID, locationID int64, flags []int64) (marshal.PyRep, error) {
	charID, stationID := ownerID, locationID
	log.Printf("[db] GetOwnerBlueprintItemsAt owner=%d location=%d flags=%v", ownerID, locationID, flags)
	if len(flags) == 0 {
		flags = []int64{4}
	}
	flagIn := ""
	flagArgs := make([]interface{}, 0, len(flags))
	for i, f := range flags {
		if i > 0 {
			flagIn += ","
		}
		flagIn += "?"
		flagArgs = append(flagArgs, f)
	}
	cols := []string{
		"itemID", "typeID", "ownerID", "locationID", "flag",
		"contraband", "singleton", "quantity", "groupID", "categoryID", "customInfo",
		"copy", "materialLevel", "productivityLevel", "licensedProductionRunsRemaining",
		"blueprintID",
	}
	rows, err := db.QueryContext(ctx,
		`SELECT e.itemID, e.typeID, e.ownerID, e.locationID, e.flag,
		        e.contraband, e.singleton, e.quantity,
		        COALESCE(t.groupID, 0), COALESCE(g.categoryID, 0),
		        COALESCE(ib.copy, 0),
		        COALESCE(ib.materialLevel, 0),
		        COALESCE(ib.productivityLevel, 0),
		        COALESCE(ib.licensedProductionRunsRemaining, -1),
		        e.itemID
		   FROM entity e
		   INNER JOIN invBlueprintTypes bpt ON bpt.blueprintTypeID = e.typeID
		   LEFT JOIN invTypes t ON t.typeID = e.typeID
		   LEFT JOIN invGroups g ON g.groupID = t.groupID
		   LEFT JOIN invBlueprints ib ON ib.blueprintID = e.itemID
		  WHERE e.ownerID = ? AND e.locationID = ? AND e.flag IN (`+flagIn+`)
		  ORDER BY e.itemID`,
		append([]interface{}{charID, stationID}, flagArgs...)...,
	)
	if err != nil {
		return nil, fmt.Errorf("GetCharStationBlueprintItems query: %w", err)
	}
	defer rows.Close()

	var result [][]marshal.PyRep
	for rows.Next() {
		var (
			itemID, typeID, ownerID, locationID int64
			flag, contraband, singleton, qty    int64
			groupID, categoryID                 int64
			copyFlag, matLevel, prodLevel       int64
			runsRemaining                       int64
		)
		var blueprintID int64
		if err := rows.Scan(&itemID, &typeID, &ownerID, &locationID,
			&flag, &contraband, &singleton, &qty,
			&groupID, &categoryID,
			&copyFlag, &matLevel, &prodLevel, &runsRemaining,
			&blueprintID); err != nil {
			return nil, fmt.Errorf("GetCharStationBlueprintItems scan: %w", err)
		}
		result = append(result, []marshal.PyRep{
			intRep(itemID), intRep(typeID), intRep(ownerID), intRep(locationID),
			intRep(flag), intRep(contraband), intRep(singleton), intRep(qty),
			intRep(groupID), intRep(categoryID), marshal.PyNone{},
			intRep(copyFlag), intRep(matLevel), intRep(prodLevel), intRep(runsRemaining),
			intRep(blueprintID),
		})
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("GetCharStationBlueprintItems rows: %w", err)
	}
	log.Printf("[db] GetCharStationBlueprintItems charID=%d stationID=%d → %d items", charID, stationID, len(result))
	return makeRowset(cols, result), nil
}

// GetCharStationsWithItems returns the InventoryBound.ListStations() rowset (stationID,
// itemCount, blueprintCount) for stations where charID has hangar items (flag 4). The S&I
// picker reads blueprintCount.
func GetCharStationsWithItems(ctx context.Context, db *sql.DB, charID int64) (marshal.PyRep, error) {
	log.Printf("[db] GetCharStationsWithItems charID=%d", charID)
	cols := []string{"stationID", "itemCount", "blueprintCount"}
	rows, err := db.QueryContext(ctx,
		`SELECT e.locationID,
		        COUNT(*) AS itemCount,
		        SUM(CASE WHEN bp.blueprintTypeID IS NOT NULL THEN 1 ELSE 0 END) AS blueprintCount
		   FROM entity e
		   LEFT JOIN invBlueprintTypes bp ON bp.blueprintTypeID = e.typeID
		   INNER JOIN staStations s ON s.stationID = e.locationID
		  WHERE e.ownerID = ? AND e.flag = 4
		  GROUP BY e.locationID
		  ORDER BY e.locationID`,
		charID,
	)
	if err != nil {
		return nil, fmt.Errorf("GetCharStationsWithItems query: %w", err)
	}
	defer rows.Close()
	var result [][]marshal.PyRep
	for rows.Next() {
		var stationID, itemCount, blueprintCount int64
		if err := rows.Scan(&stationID, &itemCount, &blueprintCount); err != nil {
			return nil, fmt.Errorf("GetCharStationsWithItems scan: %w", err)
		}
		result = append(result, []marshal.PyRep{intRep(stationID), intRep(itemCount), intRep(blueprintCount)})
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("GetCharStationsWithItems rows: %w", err)
	}
	log.Printf("[db] GetCharStationsWithItems charID=%d → %d stations", charID, len(result))
	return makeRowset(cols, result), nil
}

