// GetCharTransactions returns a util.Rowset of market transactions for characterID.
// Mirrors the `account.GetTransactions` response format expected by wallet.py.
func GetCharTransactions(ctx context.Context, db *sql.DB, charID int64) (marshal.PyRep, error) {
	txnCols := []string{
		"transactionID", "transactionDateTime", "typeID", "quantity",
		"price", "transactionType", "clientID", "regionID", "stationID",
	}
	rows, err := db.QueryContext(ctx,
		`SELECT transactionID, transactionDateTime, typeID, quantity,
		        price, transactionType, clientID, regionID, stationID
		   FROM market_transactions
		  WHERE characterID = ?
		  ORDER BY transactionDateTime DESC
		  LIMIT 500`,
		charID,
	)
	if err != nil {
		return makeRowset(txnCols, nil), nil
	}
	defer rows.Close()

	var result [][]marshal.PyRep
	for rows.Next() {
		var txnID, dt, typeID, qty, txnType, cID, rID, sID int64
		var price float64
		if err := rows.Scan(&txnID, &dt, &typeID, &qty, &price, &txnType, &cID, &rID, &sID); err != nil {
			return nil, fmt.Errorf("GetCharTransactions scan: %w", err)
		}
		result = append(result, []marshal.PyRep{
			intRep(txnID), intRep(dt), intRep(typeID), intRep(qty),
			floatRep(price), intRep(txnType), intRep(cID), intRep(rID), intRep(sID),
		})
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return makeRowset(txnCols, result), nil
}

// EmptyTransactionRowset returns an empty util.Rowset with transaction columns.
// Used as a fallback when GetCharTransactions fails.
func EmptyTransactionRowset() marshal.PyRep {
	return makeRowset([]string{
		"transactionID", "transactionDateTime", "typeID", "quantity",
		"price", "transactionType", "clientID", "regionID", "stationID",
	}, nil)
}

// ── GetCharJournal ────────────────────────────────────────────────────────────

// GetCharJournal returns a util.Rowset of wallet journal entries for characterID.
// Mirrors the MarketDB::GetJournal result used by account.GetJournal in wallet.py.
func GetCharJournal(ctx context.Context, db *sql.DB, charID int64) (marshal.PyRep, error) {
	journalCols := []string{
		"refID", "transDate", "refTypeID", "ownerID1", "ownerID2",
		"argID1", "accountKey", "amount", "balance", "reason",
	}
	rows, err := db.QueryContext(ctx,
		`SELECT refID, transDate, refTypeID, ownerID1, ownerID2,
		        argID1, accountKey, amount, balance, reason
		   FROM market_journal
		  WHERE characterID = ?
		  ORDER BY transDate DESC
		  LIMIT 500`,
		charID,
	)
	if err != nil {
		return makeRowset(journalCols, nil), nil
	}
	defer rows.Close()

	var result [][]marshal.PyRep
	for rows.Next() {
		var refID, transDate, refTypeID, ownerID1, ownerID2, accountKey int64
		var argID1 sql.NullString
		var amount, balance float64
		var reason sql.NullString
		if err := rows.Scan(&refID, &transDate, &refTypeID, &ownerID1, &ownerID2,
			&argID1, &accountKey, &amount, &balance, &reason); err != nil {
			return nil, fmt.Errorf("GetCharJournal scan: %w", err)
		}
		// argID1 is stored as VARCHAR but format.GetName compares it numerically (negative means a
		// typeID lookup), so numeric values go out as ints.
		var argRep, reasonRep marshal.PyRep
		if argID1.Valid {
			if n, err := strconv.ParseInt(argID1.String, 10, 64); err == nil {
				argRep = intRep(n)
			} else {
				argRep = strRep(argID1.String)
			}
		} else {
			argRep = marshal.PyNone{}
		}
		if reason.Valid {
			reasonRep = strRep(reason.String)
		} else {
			reasonRep = marshal.PyNone{}
		}
		result = append(result, []marshal.PyRep{
			intRep(refID), intRep(transDate), intRep(refTypeID), intRep(ownerID1), intRep(ownerID2),
			argRep, intRep(accountKey), floatRep(amount), floatRep(balance), reasonRep,
		})
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return makeRowset(journalCols, result), nil
}

// SeedStationMarket replaces the Seeder sell orders at one station with one order per
// published market type: invTypes.basePrice (100 ISK when null), quantity 9999999, region
// range. A GM tool for seeding the docked station. Returns (deleted, inserted, error).
func SeedStationMarket(ctx context.Context, db *sql.DB, stationID int64) (int64, int64, error) {
	parents, err := GetStationParents(ctx, db, stationID)
	if err != nil {
		return 0, 0, fmt.Errorf("SeedStationMarket: %w", err)
	}

	delRes, err := db.ExecContext(ctx,
		`DELETE FROM market_orders WHERE charID = ? AND stationID = ?`,
		SeederCharID, stationID)
	if err != nil {
		return 0, 0, fmt.Errorf("SeedStationMarket delete: %w", err)
	}
	deleted, _ := delRes.RowsAffected()

	now := win32TimeNow()
	insRes, err := db.ExecContext(ctx, `
		INSERT INTO market_orders
		  (typeID, charID, regionID, stationID, `+"`range`"+`, bid, price,
		   volEntered, volRemaining, issued, orderState, minVolume, contraband,
		   accountID, duration, isCorp, solarSystemID, escrow, jumps)
		SELECT
		  t.typeID, ?, ?, ?, 32767, 0,
		  COALESCE(t.basePrice, 100),
		  9999999, 9999999, ?, 1, 1, 0,
		  ?, 365, 0, ?, 0, 1
		FROM invTypes t
		WHERE t.published = 1 AND t.marketGroupID IS NOT NULL`,
		SeederCharID, parents.RegionID, stationID, now,
		SeederCharID, parents.SolarSystemID,
	)
	if err != nil {
		return deleted, 0, fmt.Errorf("SeedStationMarket insert: %w", err)
	}
	inserted, _ := insRes.RowsAffected()
	return deleted, inserted, nil
}

// SeedNPCMarketOrders purges every Seeder order and regenerates them from
// crpnpccorporationtrades: sell orders for supplyDemand > 0, buy orders for < 0, at every
// station the corporation owns. See docs/db-notes.md#npc-market-seeding.
// Returns (deleted, inserted, error).
func SeedNPCMarketOrders(ctx context.Context, db *sql.DB) (int64, int64, error) {
	// Safety check: verify crpnpccorporationtrades has data before purging.
	var tradeCount int64
	err := db.QueryRowContext(ctx,
		`SELECT COUNT(*) FROM crpnpccorporationtrades`).Scan(&tradeCount)
	if err != nil {
		return 0, 0, fmt.Errorf("SeedNPCMarketOrders: crpnpccorporationtrades table missing or empty: %w", err)
	}
	if tradeCount == 0 {
		log.Printf("SeedNPCMarketOrders: crpnpccorporationtrades is empty — skipping (existing orders preserved)")
		return 0, 0, nil
	}

	// Purge all old seeder orders.
	delRes, err := db.ExecContext(ctx,
		`DELETE FROM market_orders WHERE charID = ?`, SeederCharID)
	if err != nil {
		return 0, 0, fmt.Errorf("SeedNPCMarketOrders delete: %w", err)
	}
	deleted, _ := delRes.RowsAffected()

	// Query trade entries joined with stations and type info. t.price is the
	// optional admin override (NULL = derive the price from basePrice).
	rows, err := db.QueryContext(ctx, `
		SELECT t.corporationID, t.typeID, t.supplyDemand, t.price,
		       s.stationID, s.solarSystemID, s.regionID,
		       COALESCE(it.basePrice, 100) AS basePrice,
		       it.groupID IN (`+tradeGoodGroupList+`) AS isTradeGood,
		       COALESCE(ms.security, 1.0) AS security,
		       g.categoryID,
		       COALESCE(pw.valueInt, pw.valueFloat, 0) AS powerUse,
		       COALESCE(cp.valueInt, cp.valueFloat, 0) AS cpuUse
		  FROM crpnpccorporationtrades t
		  JOIN staStations s ON s.corporationID = t.corporationID
		  JOIN invTypes it ON it.typeID = t.typeID
		  JOIN invGroups g ON g.groupID = it.groupID
		  LEFT JOIN dgmTypeAttributes pw ON pw.typeID = t.typeID AND pw.attributeID = 30
		  LEFT JOIN dgmTypeAttributes cp ON cp.typeID = t.typeID AND cp.attributeID = 50
		  LEFT JOIN mapSolarSystems ms ON ms.solarSystemID = s.solarSystemID
		 WHERE it.published = 1 AND it.marketGroupID IS NOT NULL`)
	if err != nil {
		return deleted, 0, fmt.Errorf("SeedNPCMarketOrders query: %w", err)
	}
	defer rows.Close()

	now := win32TimeNow()

	// Build batch insert values.
	const batchSize = 5000
	var valueParts []string
	var valueArgs []interface{}
	var totalInserted int64

	flush := func() error {
		if len(valueParts) == 0 {
			return nil
		}
		query := `INSERT INTO market_orders
			(typeID, charID, regionID, stationID, ` + "`range`" + `, bid, price,
			 volEntered, volRemaining, issued, orderState, minVolume, contraband,
			 accountID, duration, isCorp, solarSystemID, escrow, jumps)
			VALUES ` + strings.Join(valueParts, ",")
		res, err := db.ExecContext(ctx, query, valueArgs...)
		if err != nil {
			return fmt.Errorf("SeedNPCMarketOrders batch insert: %w", err)
		}
		n, _ := res.RowsAffected()
		totalInserted += n
		valueParts = valueParts[:0]
		valueArgs = valueArgs[:0]
		return nil
	}

	for rows.Next() {
		var corpID, typeID int64
		var supplyDemand float64
		var priceOverride sql.NullFloat64
		var stationID, solarSystemID, regionID int64
		var basePrice, security float64
		var isTradeGood bool
		var categoryID int64
		var powerUse, cpuUse float64
		if err := rows.Scan(&corpID, &typeID, &supplyDemand, &priceOverride,
			&stationID, &solarSystemID, &regionID, &basePrice, &isTradeGood,
			&security, &categoryID, &powerUse, &cpuUse); err != nil {
			return deleted, totalInserted, fmt.Errorf("SeedNPCMarketOrders scan: %w", err)
		}
		tier := tierForSec(security)

		// An admin price override is used exactly as entered: no jitter, discount or tiering.
		var bid int
		var price float64
		if supplyDemand > 0 {
			bid = 0
		} else {
			bid = 1
		}
		if priceOverride.Valid && priceOverride.Float64 > 0 {
			price = priceOverride.Float64
		} else if isTradeGood {
			// Trade goods seed with a hauling margin (marketsec.go); TickNPCMarketDynamics walks the
			// prices from there.
			if bid == 0 {
				lo := mkt().secTradeSellLo[tier]
				price = basePrice * (lo + rand.Float64()*(1.0-lo))
			} else {
				price = basePrice * (mkt().secTradeBuyLo[tier] + rand.Float64()*mkt().secTradeBuySpan[tier])
			}
		} else {
			jitter := 1.0 + (rand.Float64()*0.10 - 0.05) // ±5%
			if bid == 0 {
				price = basePrice * jitter
				if categoryID == moduleCategoryID && price < moduleAskFloor {
					price = moduleAskPrice(powerUse, cpuUse) * jitter
					if price < moduleAskFloor {
						price = moduleAskFloor
					} else if price > moduleAskCeil {
						price = moduleAskCeil
					}
				}
			} else {
				price = basePrice * mkt().npcBuyFactor * mkt().secBidMul[tier] * jitter
			}
		}
		if price < 0.01 {
			price = 0.01
		}
		// Volume scales from supplyDemand (a fraction) and the tier's depth: highsec bids are
		// shallow, low/null deep.
		volume := int64(math.Abs(supplyDemand) * 10000 * mkt().secVolMul[tier])
		if isTradeGood {
			volume = int64(float64(volume) * mkt().tradeGoodVolMul)
		}
		if volume < 1 {
			volume = 1
		}
		if volume > 999999 {
			volume = 999999
		}

		// Buy orders are station-only so sellers must haul to the NPC; sell orders stay region-wide.
		orderRange := int64(rangeRegion)
		if bid == 1 {
			orderRange = rangeStation
		}
		valueParts = append(valueParts, "(?,?,?,?,?,?,?,?,?,?,1,1,0,?,365,0,?,0,1)")
		valueArgs = append(valueArgs,
			typeID, SeederCharID, regionID, stationID, orderRange,
			bid, price,
			volume, volume, now,
			corpID, solarSystemID,
		)

		if len(valueParts) >= batchSize {
			if err := flush(); err != nil {
				return deleted, totalInserted, err
			}
		}
	}
	if err := rows.Err(); err != nil {
		return deleted, totalInserted, fmt.Errorf("SeedNPCMarketOrders rows: %w", err)
	}
	if err := flush(); err != nil {
		return deleted, totalInserted, err
	}

	// A corp with supply and demand rows for one type would seed a bid above its own ask;
	// clamp so same-station round trips never pay.
	if err := ClampNPCBidsBelowLocalAsks(ctx, db); err != nil {
		return deleted, totalInserted, err
	}

	return deleted, totalInserted, nil
}

// npcBuyFactor (default 0.90, server_settings market.npcBuyFactor via mkt() in marketsec.go)
// is the buy/sell spread that keeps same-station round trips unprofitable.

// A category-7 sell order priced under moduleAskFloor (modules ship with basePrice 0) is
// lifted into [moduleAskFloor, moduleAskCeil] by moduleAskPrice. Admin overrides and buy
// orders are untouched. See docs/db-notes.md#npc-market-seeding.
const (
	moduleCategoryID = 7
	moduleAskFloor   = 10000.0
	moduleAskCeil    = 20000.0
	moduleFitScale   = 2500.0 // largest powergrid draw among shipped modules
)

// moduleAskPrice maps a module's powergrid + CPU draw to an ask inside the module band,
// log-scaled so midrange modules spread out instead of bunching at the floor.
func moduleAskPrice(powerUse, cpuUse float64) float64 {
	fit := powerUse + cpuUse
	if fit < 0 {
		fit = 0
	}
	pos := math.Log1p(fit) / math.Log1p(moduleFitScale)
	if pos > 1 {
		pos = 1
	}
	return moduleAskFloor + (moduleAskCeil-moduleAskFloor)*pos
}

// SeedOreDemand inserts Seeder bids for ore and ice (category 25) at every station of an
// NPC mining corporation (mainActivityID = 3), since crpnpccorporationtrades has no ore
// demand. Price is basePrice * npcBuyFactor * the tier bid multiplier. Minerals (group 18)
// are never bid for. See docs/db-notes.md#npc-market-seeding.
func SeedOreDemand(ctx context.Context, db *sql.DB) (int64, error) {
	secExpr := "COALESCE(ms.security, 1.0)"
	res, err := db.ExecContext(ctx, `
		INSERT INTO market_orders
		  (typeID, charID, regionID, stationID, `+"`range`"+`, bid, price,
		   volEntered, volRemaining, issued, orderState, minVolume, contraband,
		   accountID, duration, isCorp, solarSystemID, escrow, jumps)
		SELECT
		  t.typeID, ?, s.regionID, s.stationID, 32767, 1,
		  GREATEST(0.01, ROUND(COALESCE(t.basePrice, 100) * ? * `+secCase(secExpr, mkt().secBidMul)+`, 2)),
		  GREATEST(1, ROUND(IF(g.categoryID = 25, 500000, 200000) * `+secCase(secExpr, mkt().secVolMul)+`)),
		  GREATEST(1, ROUND(IF(g.categoryID = 25, 500000, 200000) * `+secCase(secExpr, mkt().secVolMul)+`)),
		  ?, 1, 1, 0, c.corporationID, 365, 0, s.solarSystemID, 0, 1
		FROM invTypes t
		JOIN invGroups g ON g.groupID = t.groupID
		JOIN crpnpccorporations c ON c.mainActivityID = 3
		JOIN staStations s ON s.corporationID = c.corporationID
		LEFT JOIN mapSolarSystems ms ON ms.solarSystemID = s.solarSystemID
		WHERE t.published = 1 AND t.marketGroupID IS NOT NULL
		  AND g.categoryID = 25`,
		SeederCharID, mkt().npcBuyFactor, win32TimeNow(),
	)
	if err != nil {
		return 0, fmt.Errorf("SeedOreDemand: %w", err)
	}
	n, _ := res.RowsAffected()
	return n, nil
}

// RecordDailyPriceSnapshots inserts one synthetic market transaction per (region, type) at
// the best live Seeder sell price (auto and admin), so the price chart draws a line for
// untraded types. Synthetic rows older than 60 days are pruned.
func RecordDailyPriceSnapshots(ctx context.Context, db *sql.DB) (int64, error) {
	const win32Day = uint64(864000000000)
	cutoff := win32TimeNow() - 60*win32Day
	if _, err := db.ExecContext(ctx, `
		DELETE FROM market_transactions
		 WHERE characterID = ? AND transactionDateTime < ?`,
		SeederCharID, cutoff,
	); err != nil {
		return 0, fmt.Errorf("RecordDailyPriceSnapshots prune: %w", err)
	}

	res, err := db.ExecContext(ctx, `
		INSERT INTO market_transactions
		  (transactionDateTime, typeID, quantity, price, transactionType, characterID, clientID, regionID, stationID)
		SELECT ?, o.typeID, FLOOR(50 + RAND() * 450), MIN(o.price),
		       1, ?, ?, o.regionID, 0
		  FROM market_orders o
		 WHERE o.charID IN (?, ?) AND o.bid = 0 AND o.orderState = 1
		 GROUP BY o.regionID, o.typeID`,
		win32TimeNow(), SeederCharID, SeederCharID, SeederCharID, AdminSeederCharID,
	)
	if err != nil {
		return 0, fmt.Errorf("RecordDailyPriceSnapshots insert: %w", err)
	}
	n, _ := res.RowsAffected()
	return n, nil
}
